/**
 * Pidfile lock shared by hooks that must collapse N concurrent sessions into
 * ONE unit of work (#3705 security scan, #3708 debt ledger).
 *
 * Semantics: `acquire` returns true only for the process that now holds the
 * lock. A lock is stolen when its holder pid is dead or when the file is older
 * than `staleMs` (a crashed holder never releases). Losing a race to another
 * live holder returns false and the caller skips its work; for advisory hooks
 * skipping is the correct outcome, not an error.
 */

import { readFileSync, statSync, unlinkSync, writeFileSync } from 'node:fs';

function isPidAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

export function acquirePidLock(lockPath: string, staleMs: number): boolean {
  try {
    writeFileSync(lockPath, String(process.pid), { flag: 'wx' });
    return true;
  } catch {
    try {
      const holderPid = Number.parseInt(readFileSync(lockPath, 'utf8'), 10);
      const age = Date.now() - statSync(lockPath).mtimeMs;
      const abandoned =
        age > staleMs || !Number.isInteger(holderPid) || holderPid <= 0 || !isPidAlive(holderPid);
      if (abandoned) {
        unlinkSync(lockPath);
        writeFileSync(lockPath, String(process.pid), { flag: 'wx' });
        return true;
      }
    } catch {
      // Lost the race to another process, or the lock vanished mid-check.
    }
    return false;
  }
}

export function releasePidLock(lockPath: string): void {
  try {
    if (readFileSync(lockPath, 'utf8') === String(process.pid)) {
      unlinkSync(lockPath);
    }
  } catch {
    // Already gone, or stolen after staleness: nothing to release.
  }
}
